import{_ as d,S as r,n as c,p as h,q as t,J as s,C as n,A as i,a2 as l}from"./framework-c4fdf794.js";const u="/images/user_files.png",g="/images/user_files_scanning.png",p="/images/history_user.png",f="/images/ignore_list_user.png",m="/images/uam_user_overview.png",b="/images/uam_user_add_rule.png",w={},y={class:"table-of-contents"},v={class:"notranslate"},k={class:"notranslate"};function I(x,e){const a=r("router-link"),o=r("RouterLink");return c(),h("div",null,[e[11]||(e[11]=t("h1",{id:"user-interface",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#user-interface","aria-hidden":"true"},"#"),s(" User Interface")],-1)),e[12]||(e[12]=t("p",null,"There are following tabs in the Imunify360 end user interface:",-1)),t("nav",y,[t("ul",null,[t("li",null,[n(a,{to:"#files"},{default:i(()=>[...e[0]||(e[0]=[s("Files",-1)])]),_:1})]),t("li",null,[n(a,{to:"#history"},{default:i(()=>[...e[1]||(e[1]=[s("History",-1)])]),_:1})]),t("li",null,[n(a,{to:"#ignore-list"},{default:i(()=>[...e[2]||(e[2]=[s("Ignore List",-1)])]),_:1})]),t("li",null,[n(a,{to:"#webshield"},{default:i(()=>[...e[3]||(e[3]=[s("WebShield",-1)])]),_:1}),t("ul",null,[t("li",null,[n(a,{to:"#under-attack-mode"},{default:i(()=>[...e[4]||(e[4]=[s("Under Attack Mode",-1)])]),_:1})])])])])]),e[13]||(e[13]=l('<h2 id="files" tabindex="-1"><a class="header-anchor" href="#files" aria-hidden="true">#</a> Files</h2><p>Go to Imunify360 → Malicious tab. Here, there is a table with a list of infected files.</p><p><img src="'+u+'" alt=""></p><p>The table has the following columns:</p><ul><li><strong>Detected</strong> — displays the exact time when a file was detected as malicious</li><li><strong>File</strong> — the path where the file is located starting with root</li><li><strong>Reason</strong> — describes the signature which was detected during the scanning process. Names in this column depend on the signature vendor. You can derive some information from the signature ID itself. <code>SMW-SA-05155-wshll</code> – in this Signature ID: <ul><li>The first section can be either <code>SMW</code> or <code>CMW</code>. <code>SMW</code> stands for Server Malware and <code>CMW</code> stands for Client Malware</li><li>The second section of ID can be either <code>INJ</code> or <code>SA</code>. <code>INJ</code> stands for Injection (means Malware is Injected to some legitimate file) and <code>SA</code> stands for StandAlone (means File is Completely Malicious)</li><li>The third section is <code>05155</code>. This is simply an identification number for the signature.</li><li>The fourth section <code>wshll/mlw.wp/etc</code> explains the category and class of malware identified. Here, <code>wshll</code> stands for web shell (<code>mlw</code> stands for malware).</li><li>The fifth section is <code>0</code>, which provides the version number of the signature.</li></ul></li><li><strong>Status</strong> — displays the file status: <ul><li><strong>Infected</strong> — threat was detected after scanning. If a file was not cleaned after cleanup, the info icon is displayed. Hover mouse over info icon to display the reason</li><li><strong>Cleaned</strong> — infected file is cleaned up</li><li><strong>Content removed</strong> — a file content was removed after cleanup</li><li><strong>Cleanup queued</strong> — infected file is queued for cleanup. Actions:</li></ul></li><li><strong>Add to Ignore List</strong> — add file to Ignore List and remove it from the Malicious files list. Note that if a file is added to Ignore List, Imunify360 will no longer scan this file</li><li><strong>View file</strong> — click <em>eye</em> icon in the file line and the file content will be displayed in the popup. Only the first 100Kb of the file content will be shown in case if a file has bigger size</li><li><strong>Cleanup</strong> — click to cleanup the file.</li><li><strong>Delete</strong> — remove the file from the server and from the list of Malicious files.</li><li><strong>Restore original</strong> — click <em>Restore original</em> to restore original file after cleaning up if backup is available.</li></ul><p>To perform a bulk action, tick required users and click the corresponding button above the table.</p><p>The following filters are available:</p><ul><li><strong>Timeframe</strong> — displays the results filtered by chosen period or date.</li><li><strong>Status</strong> — displays the results filtered by chosen status.</li><li><strong>Items per page displayed</strong> — click the number at the table bottom.</li></ul><p>The table can be sorted by detection date (Detected), file path (File), Reason, and Status.</p><p>If a user is allowed by an administrator to scan his files, he can see the <em>Start scanning</em> button.</p><p><img src="'+g+'" alt=""></p><h2 id="history" tabindex="-1"><a class="header-anchor" href="#history" aria-hidden="true">#</a> History</h2><p>History tab contains data of all actions for all files. Go to Imunify360 → History tab. Here, there is a table with a list of files.</p><p><img src="'+p+'" alt=""></p><p>The table has the following columns:</p><ul><li><strong>Date</strong> — action timestamp.</li><li><strong>Path to File</strong> — path to the file starting from the root.</li><li><strong>Cause</strong> — displays the way malicious file was found: <ul><li><strong>Manual</strong> — scanning or cleaning was manually processed by a user.</li><li><strong>On-demand</strong> — scanning or cleaning was initiated/made by a user;</li><li><strong>Real time</strong> — scanning or cleaning was automatically processed by the system.</li></ul></li><li><strong>Owner</strong> — displays a user name of file owner.</li><li><strong>Initiator</strong> — displays the name of a user who was initiated the action. For system actions the name is System.</li><li><strong>Event</strong> — displays the action with the file: <ul><li><strong>Detected as malicious</strong> — after scanning the file was detected as infected;</li><li><strong>Cleaned</strong> — the file is cleaned up.</li><li><strong>Failed to clean up</strong> — there was a problem during cleanup. Hover mouse over the info icon to read more.</li><li><strong>Added to Ignore List</strong> — the file was added to Ignore List. Imunify360 will not scan it.</li><li><strong>Restored original</strong> — file content was restored as not malicious.</li><li><strong>Cleanup removed content</strong> — file contend was removed after cleanup.</li><li><strong>Deleted from Ignore List</strong> — the file was removed from Ignore List. Imunify360 will scan it.</li><li><strong>Deleted</strong> — the file was deleted.</li><li><strong>Submitted for analysis</strong> — the file was submitted to Imunify team for analysis.</li><li><strong>Failed to delete</strong> — there was a problem during removal. Hover mouse over the info icon to read more.</li><li><strong>Failed to ignore</strong> — there was a problem during adding to Ignore List. Hover mouse over the info icon to read more.</li><li><strong>Failed to delete from ignore</strong> — there was a problem during removal from Ignore List. Hover mouse over the info icon to read more.</li></ul></li></ul><p>The table can be sorted by Date, Path to File, Cause, and Owner.</p><h2 id="ignore-list" tabindex="-1"><a class="header-anchor" href="#ignore-list" aria-hidden="true">#</a> Ignore List</h2><p>Ignore List tab contains the list of files and directories that are excluded from Malware Scanner scanning. Go to Imunify360 → Ignore List tab. Here, there is a table with a list of files.</p><p><img src="'+f+`" alt=""></p><p>The table has the following columns:</p><ul><li><strong>Added</strong> — the date when the file was added to Ignore List.</li><li><strong>Path</strong> — path to the file starting from the root.</li><li><strong>Actions</strong>: <ul><li><strong>Remove from Ignore List</strong> — click <em>Bin</em> icon to remove the file from the Ignore List and start scanning.</li><li><strong>Add new file or directory</strong> — click <em>Plus</em> icon to add a new file or directory to Ignore List. To perform a bulk action, tick required files and click the corresponding button above the table.</li></ul></li></ul><p>The following filters are available:</p><ul><li><strong>Timeframe</strong> — displays the results filtered by chosen period or date.</li><li><strong>Items per page displayed</strong> — click the number at the table bottom.</li></ul><p>The table can be sorted by Added and Path. By default, it is sorted from newest to oldest.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>The end-user malware ignore list is disabled by default. Only Imunify360 administrators can enable it:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;PERMISSIONS&quot;: {&quot;user_ignore_list&quot;: true}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>For disabling:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-agent config update &#39;{&quot;PERMISSIONS&quot;: {&quot;user_ignore_list&quot;: false}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><h2 id="webshield" tabindex="-1"><a class="header-anchor" href="#webshield" aria-hidden="true">#</a> WebShield</h2><p>The <span class="notranslate">WebShield</span> tab holds the WebShield protection features you can manage for your own domains. Currently it contains one such feature, <span class="notranslate">Under Attack Mode</span>.</p><h3 id="under-attack-mode" tabindex="-1"><a class="header-anchor" href="#under-attack-mode" aria-hidden="true">#</a> Under Attack Mode</h3><p><span class="notranslate"><strong>Under Attack Mode (UAM)</strong></span> lets you put your own domains &quot;under attack&quot;: while a domain is under attack, every visitor first gets a JavaScript splash page and only reaches the site after their browser solves it. Regular browsers solve it transparently and are then trusted for the lifetime of the clearance cookie; simple bots never get through.</p><p>Turn it on for a domain when it is the target of an automated flood — a scripted login or checkout abuse, for example — and turn it off once the flood is over.</p><p><img src="`+m+'" alt=""></p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This tab appears only if <span class="notranslate">Under Attack Mode</span> is supported by the server, the server administrator has enabled it, and they have allowed end users to manage their own rules. If you do not see the tab, or you see a notice saying that the service is disabled, ask your hosting provider.</p></div><p>You only see and manage the rules you created, for the domains of your own account. Rules created by the server administrator are not shown here, but they still apply to your domains.</p><h4 id="adding-a-rule" tabindex="-1"><a class="header-anchor" href="#adding-a-rule" aria-hidden="true">#</a> Adding a rule</h4><p>Click <span class="notranslate"><strong>ADD</strong></span> and fill in the form.</p><p><img src="'+b+'" alt=""></p><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><span class="notranslate">Domain</span></td><td>The domain to put under attack. Pick one of your domains from the list, or enter its wildcard — <span class="notranslate"><code>*.example.com</code></span> covers the subdomains only, <span class="notranslate"><code>.example.com</code></span> covers the domain and its subdomains.</td></tr><tr><td><span class="notranslate">Clearance cookie lifetime</span></td><td>How long a visitor is trusted after solving the splash page, before being asked again. The default is <span class="notranslate"><code>1h</code></span>; a shorter lifetime is stricter, a longer one is more comfortable for real visitors.</td></tr><tr><td><span class="notranslate">Label</span></td><td>An optional note to remind you why the rule exists.</td></tr><tr><td><span class="notranslate">Paths</span></td><td><span class="notranslate"><strong>Entire domain</strong></span> challenges every request. <span class="notranslate"><strong>Only the listed paths</strong></span> challenges just the URLs you list — useful when only the login or the checkout page is being hit. <span class="notranslate"><strong>All paths except the listed ones</strong></span> challenges everything else, which is a way to keep an API or a webhook endpoint reachable.</td></tr></tbody></table>',38)),t("p",null,[e[6]||(e[6]=s("The path conditions and the way they treat query strings are described in ",-1)),t("span",v,[n(o,{to:"/dashboard/#scoping-a-rule-to-paths"},{default:i(()=>[...e[5]||(e[5]=[s("Scoping a rule to paths",-1)])]),_:1})]),e[7]||(e[7]=s(".",-1))]),e[14]||(e[14]=l('<h4 id="checking-and-managing-rules" tabindex="-1"><a class="header-anchor" href="#checking-and-managing-rules" aria-hidden="true">#</a> Checking and managing rules</h4><ul><li><span class="notranslate"><strong>Test URL against the rules</strong></span> tells you whether a given URL would be challenged, without waiting for real traffic.</li><li><span class="notranslate">Hits for</span> shows how many challenges the rule has served over the selected period, so you can see whether it is doing any work.</li><li>The <span class="notranslate"><strong>Active</strong></span> switch pauses a rule and resumes it later — better than deleting a rule you will need again during the next flood.</li><li><span class="notranslate"><strong>Edit</strong></span> changes the cookie lifetime, the label and the paths of an existing rule. The domain cannot be changed; create a new rule instead.</li><li><span class="notranslate"><strong>Remove</strong></span> deletes the rule.</li></ul><div class="warning custom-block"><p class="custom-block-title">Legitimate automation needs to be whitelisted</p><p>Anything that cannot run JavaScript is stopped while the rule is active — including your own integrations, monitoring and cron jobs that call the site over HTTP. Ask your hosting provider to whitelist the IP addresses they come from; whitelisted IP addresses are not challenged.</p></div>',3)),t("p",null,[e[9]||(e[9]=s("For the technical details of how the challenge is enforced, see ",-1)),t("span",k,[n(o,{to:"/features/under_attack_mode/"},{default:i(()=>[...e[8]||(e[8]=[s("Under Attack Mode (UAM)",-1)])]),_:1})]),e[10]||(e[10]=s(".",-1))])])}const S=d(w,[["render",I],["__file","index.html.vue"]]);export{S as default};
